<?php
declare(strict_types=1);
require_once __DIR__.'/bootstrap.php';
require_once __DIR__.'/FinancialClosePolicy.php';
require_once __DIR__.'/FinancialCutoff.php';
require_once __DIR__.'/CashFundReports.php';
require_once __DIR__.'/FinanceAccess.php';
/** Typed account-wide reconciliation. Every close is an append-only revision;
 * statement sources and book corrections cannot be supplied as balancing plugs. */
final class BankReconciliation {
    public const KINDS=['DEPOSIT_IN_TRANSIT','BANK_ERROR_ADD','BANK_ERROR_SUBTRACT','BANK_CHARGE','BANK_INTEREST','BOOK_ERROR_ADD','BOOK_ERROR_SUBTRACT'];
    public function __construct(private PDO $db,private array $user){}
    private function auth(int $org,bool $write=false):array {$o=FinanceAccess::read($this->db,$this->user,$org);if($write){demand(FinancialCutoff::isCoordinated($this->db),'Use a coordinated READ COMMITTED financial transaction',409);allowedToWrite($this->user);demand($this->user['role']==='SUPER_ADMIN'||($this->user['role']===$o['kind']&&in_array($o['kind'],['SCHOOL','DIVISION'],true)),'School finance is read-only for Division users',403);}return $o;}
    private function bank(int $org,int $bank,bool $lock=false):array {$r=one($this->db,'SELECT * FROM bank_accounts WHERE id=? AND organization_id=?'.($lock?' FOR UPDATE':''),[$bank,$org]);demand($r!==null,'Bank does not belong to workspace',403);return $r;}
    private static function period(array $d):string {$p=requiredString($d,'period',7);demand(preg_match('/^20\d\d-(0[1-9]|1[0-2])$/D',$p)===1,'Period must be YYYY-MM');return $p;}
    private static function signed(mixed $n):int {demand(is_string($n),'Use an exact decimal monetary string');return str_starts_with($n,'-')?-moneyCents(substr($n,1)):moneyCents($n);}
    private function latest(int $org,string $key):?array {return one($this->db,'SELECT id,config_json FROM configuration_versions WHERE organization_id=? AND config_key=? ORDER BY id DESC LIMIT 1',[$org,$key]);}
    private function append(int $org,string $key,array $body,string $reason,string $event):int {q($this->db,'INSERT INTO configuration_versions(organization_id,config_key,config_json,effective_from,review_note) VALUES (?,?,?,?,?)',[$org,$key,json_encode($body,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES),date('Y-m-d'),$reason]);$id=(int)$this->db->lastInsertId();q($this->db,'INSERT INTO audit_events(organization_id,actor_id,event_type,entity_type,entity_id,details) VALUES (?,?,?,?,?,?)',[$org,$this->user['id'],$event,'BANK_RECONCILIATION',$id,json_encode(['bank_account_id'=>$body['bank_account_id'],'period'=>$body['period']??null,'predecessor_id'=>$body['predecessor_id']??0,'reason'=>$reason],JSON_THROW_ON_ERROR)]);return $id;}
    public static function maintaining(PDO $db,int $org,int $bank):int {
        $r=one($db,'SELECT config_json FROM configuration_versions WHERE organization_id=? AND config_key=? ORDER BY id DESC LIMIT 1',[$org,'FR456_BANK_BASE_'.$bank]);if($r)return (int)(json_decode($r['config_json'],true,512,JSON_THROW_ON_ERROR)['maintaining_cents']??0);
        foreach(q($db,"SELECT r.notes FROM bank_reconciliations r JOIN bank_accounts b ON b.id=r.bank_account_id WHERE b.organization_id=? AND r.bank_account_id=? AND r.status='CLOSED' ORDER BY r.period DESC,r.id DESC",[$org,$bank])->fetchAll() as $legacy){$notes=(string)$legacy['notes'];if(!str_contains($notes,'REQUIRED_MINIMUM_PHP='))continue;preg_match_all('/(?:^|[\s;])REQUIRED_MINIMUM_PHP=([0-9]{1,14}(?:\.[0-9]{1,2})?)(?=$|[\s;])/D',$notes,$matches);demand(count($matches[1])===1&&substr_count($notes,'REQUIRED_MINIMUM_PHP=')===1,'Legacy maintaining-balance evidence is ambiguous or invalid; verify it before financial posting',409);return moneyCents($matches[1][0]);}return 0;
    }
    public static function bookAdjustments(PDO $db,int $org,int $bank,string $end):int {$n=0;foreach(q($db,'SELECT kind,amount FROM bank_reconciliation_sources WHERE organization_id=? AND bank_account_id=? AND effective_date<=?',[$org,$bank,$end])->fetchAll() as $s){$v=moneyCents((string)$s['amount']);if(in_array($s['kind'],['BANK_INTEREST','BOOK_ERROR_ADD'],true))$n+=$v;elseif(in_array($s['kind'],['BANK_CHARGE','BOOK_ERROR_SUBTRACT'],true))$n-=$v;}return $n;}
    public function opening(array $d):array {
        $org=idOf($d,'organization_id');$this->auth($org,true);FinancialCutoff::beginWriter($this->db,$this->user,'finance.review.bank',$d);$bank=idOf($d,'bank_account_id');$this->bank($org,$bank,true);
        demand($this->latest($org,'FR456_BANK_BASE_'.$bank)===null,'Verified opening is immutable; an audited book correction is required',409);
        $date=requiredString($d,'start_date',10);demand(FinancialClosePolicy::day($date)&&substr($date,8)==='01'&&$date<=date('Y-m-d'),'Opening must be a nonfuture first day of month');
        // The opening may not silently swallow any recorded bank movement.
        demand(one($this->db,"SELECT id FROM fund_events WHERE organization_id=? AND bank_account_id=? AND event_type='ALLOTMENT' AND bank_credit_date<? LIMIT 1",[$org,$bank,$date])===null,'Opening would conceal recorded earlier credits',409);
        demand(one($this->db,'SELECT id FROM checks WHERE organization_id=? AND bank_account_id=? AND created_at<? LIMIT 1',[$org,$bank,$date.' 00:00:00'])===null,'Opening would conceal recorded earlier checks',409);
        demand(one($this->db,'SELECT id FROM bank_reconciliation_sources WHERE organization_id=? AND bank_account_id=? AND effective_date<? LIMIT 1',[$org,$bank,$date])===null,'Opening would conceal recorded earlier adjustment sources',409);
        $balance=self::signed($d['opening_balance']??null);$minimum=moneyCents(requiredString($d,'maintaining_balance',24));demand($balance>=0&&$minimum>=0,'Opening and maintaining balances must be nonnegative');
        $reason=requiredString($d,'reason',500);$body=['schema'=>2,'bank_account_id'=>$bank,'start_date'=>$date,'opening_cents'=>$balance,'maintaining_cents'=>$minimum,'statement_evidence'=>requiredString($d,'statement_evidence',255),'book_evidence'=>requiredString($d,'book_evidence',255),'verification_reference'=>requiredString($d,'verification_reference',255),'actor_id'=>(int)$this->user['id'],'captured_at'=>date('c'),'provenance'=>'VERIFIED_ONBOARDING_OPENING'];
        $id=$this->append($org,'FR456_BANK_BASE_'.$bank,$body,$reason,'BANK_OPENING_VERIFIED');return ['version_id'=>$id,'opening'=>$body];
    }
    public function source(array $d):array {
        $org=idOf($d,'organization_id');$this->auth($org,true);FinancialCutoff::beginWriter($this->db,$this->user,'finance.review.bank',$d);$bank=idOf($d,'bank_account_id');$this->bank($org,$bank,true);
        $kind=requiredString($d,'kind',32);
        if($kind==='SOURCE_RESOLVED'){
            $id=idOf($d,'source_id');$original=one($this->db,'SELECT * FROM bank_reconciliation_sources WHERE id=? AND organization_id=? AND bank_account_id=?',[$id,$org,$bank]);
            demand($original!==null&&in_array($original['kind'],['DEPOSIT_IN_TRANSIT','BANK_ERROR_ADD','BANK_ERROR_SUBTRACT'],true),'Only verified bank-side timing/error sources can be resolved',409);
            $date=requiredString($d,'effective_date',10);FinancialCutoff::assertOpen($this->db,$org,$date);demand($date>=$original['effective_date']&&$date<=date('Y-m-d'),'Invalid source resolution date');
            $key='FR456_BANK_RESOLVE_'.$bank.'_'.$id;demand($this->latest($org,$key)===null,'Source resolution already recorded',409);
            $body=['bank_account_id'=>$bank,'source_id'=>$id,'resolved_date'=>$date,'evidence_reference'=>requiredString($d,'evidence_reference',255),'statement_reference'=>requiredString($d,'statement_reference',255),'verification_reference'=>requiredString($d,'verification_reference',255),'actor_id'=>(int)$this->user['id']];
            $v=$this->append($org,$key,$body,requiredString($d,'reason',500),'BANK_SOURCE_RESOLVED');return ['source_id'=>$id,'resolution_version_id'=>$v];
        }
        demand(in_array($kind,self::KINDS,true),'Unsupported adjustment source kind');$date=requiredString($d,'effective_date',10);FinancialCutoff::assertOpen($this->db,$org,$date);demand($date<=date('Y-m-d'),'Adjustment cannot be future dated');
        $base=$this->latest($org,'FR456_BANK_BASE_'.$bank);if($base){$opening=json_decode($base['config_json'],true,512,JSON_THROW_ON_ERROR);demand($date>=$opening['start_date'],'Adjustment predates verified ledger opening',409);}
        $amount=moneyCents(requiredString($d,'amount',24));demand($amount>0,'Adjustment amount must be positive');$event=null;$line=null;
        if($kind==='DEPOSIT_IN_TRANSIT'){$event=idOf($d,'fund_event_id');$r=one($this->db,"SELECT * FROM fund_events WHERE id=? AND organization_id=? AND bank_account_id=? AND event_type='ALLOTMENT'",[$event,$org,$bank]);demand($r!==null&&$r['bank_credit_date']===$date&&moneyCents((string)$r['amount'])===$amount,'Deposit must match an exact recorded account credit and date',409);demand(one($this->db,'SELECT id FROM bank_reconciliation_sources WHERE fund_event_id=?',[$event])===null,'Deposit already has a bank verification source',409);}
        if(in_array($kind,['BOOK_ERROR_ADD','BOOK_ERROR_SUBTRACT'],true)){
            $line=idOf($d,'accounting_line_id');$r=one($this->db,"SELECT a.*,v.dv_id,v.version_no,d.gross FROM voucher_accounting_lines a JOIN dv_accounting_versions v ON v.id=a.accounting_version_id JOIN disbursement_vouchers d ON d.id=v.dv_id WHERE a.id=? AND d.organization_id=? AND d.status='FINALIZED' AND v.id=(SELECT x.id FROM dv_accounting_versions x WHERE x.dv_id=d.id ORDER BY x.version_no DESC,x.id DESC LIMIT 1)",[$line,$org]);
            demand($r!==null&&(int)$r['version_no']>1&&str_starts_with((string)$r['uacs_code'],'101'),'Book correction requires a distinct latest approved adjusting accounting version; original check credits are already included',409);
            $previous=one($this->db,'SELECT id FROM dv_accounting_versions WHERE dv_id=? AND version_no<? ORDER BY version_no DESC,id DESC LIMIT 1',[$r['dv_id'],$r['version_no']]);demand($previous!==null,'Earlier approved journal required for an exact cash correction delta',409);
            $cashByVersion=[];$delta=0;foreach([(int)$previous['id']=>-1,(int)$r['accounting_version_id']=>1] as $version=>$direction){$debits=$credits=$cash=0;foreach(q($this->db,'SELECT uacs_code,debit,credit FROM voucher_accounting_lines WHERE accounting_version_id=? ORDER BY id',[$version])->fetchAll() as $a){$debit=moneyCents((string)$a['debit']);$credit=moneyCents((string)$a['credit']);$debits+=$debit;$credits+=$credit;if(str_starts_with((string)$a['uacs_code'],'101'))$cash+=$debit-$credit;}demand($debits>0&&$debits===$credits,'Both approved journals must balance before applying a bank-book correction',409);$cashByVersion[$version]=$cash;$delta+=$direction*$cash;}
            $first=one($this->db,'SELECT id FROM dv_accounting_versions WHERE dv_id=? ORDER BY version_no,id LIMIT 1',[$r['dv_id']]);$originalCash=0;foreach(q($this->db,'SELECT uacs_code,debit,credit FROM voucher_accounting_lines WHERE accounting_version_id=?',[$first['id']])->fetchAll() as $a)if(str_starts_with((string)$a['uacs_code'],'101'))$originalCash+=moneyCents((string)$a['debit'])-moneyCents((string)$a['credit']);$postedPrior=0;foreach(q($this->db,'SELECT s.kind,s.amount FROM bank_reconciliation_sources s JOIN voucher_accounting_lines a ON a.id=s.accounting_line_id JOIN dv_accounting_versions v ON v.id=a.accounting_version_id WHERE s.organization_id=? AND s.bank_account_id=? AND v.dv_id=?',[$org,$bank,$r['dv_id']])->fetchAll() as $posted)$postedPrior+=($posted['kind']==='BOOK_ERROR_ADD'?1:-1)*moneyCents((string)$posted['amount']);demand($postedPrior===$cashByVersion[(int)$previous['id']]-$originalCash,'Earlier approved cash-journal corrections must be verified before later deltas can affect the bank book',409);
            demand($delta===($kind==='BOOK_ERROR_ADD'?1:-1)*$amount,'Book correction must equal the exact signed change between approved cash journals',409);
            demand(one($this->db,'SELECT id FROM checks WHERE dv_id=? AND bank_account_id=? AND organization_id=?',[$r['dv_id'],$bank,$org])!==null,'Correction accounting belongs to another bank',409);
            demand(one($this->db,'SELECT s.id FROM bank_reconciliation_sources s JOIN voucher_accounting_lines a ON a.id=s.accounting_line_id WHERE a.accounting_version_id=? LIMIT 1',[$r['accounting_version_id']])===null,'Adjusting accounting version has already affected the bank book',409);
        }
        $values=[$org,$bank,$kind,$date,moneyString($amount),requiredString($d,'evidence_reference',255),requiredString($d,'statement_reference',255),requiredString($d,'verification_reference',255),requiredString($d,'source_reference',100),$event,$line,$this->user['id']];
        q($this->db,'INSERT INTO bank_reconciliation_sources(organization_id,bank_account_id,kind,effective_date,amount,evidence_reference,statement_reference,verification_reference,source_reference,fund_event_id,accounting_line_id,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)',$values);$id=(int)$this->db->lastInsertId();
        $sourceReason=trim((string)($d['reason']??''));demand(mbSafeLen($sourceReason)<=500,'Source reason exceeds permitted length');$treatment=in_array($kind,['BOOK_ERROR_ADD','BOOK_ERROR_SUBTRACT'],true)?'EXISTING_APPROVED_ADJUSTING_JOURNAL':'RECONCILING_ITEM_ONLY_NO_LEDGER_POST';
        q($this->db,'INSERT INTO audit_events(organization_id,actor_id,event_type,entity_type,entity_id,details) VALUES (?,?,?,?,?,?)',[$org,$this->user['id'],'BANK_SOURCE_VERIFIED','BANK_SOURCE',$id,json_encode(['bank_account_id'=>$bank,'kind'=>$kind,'effective_date'=>$date,'amount_cents'=>$amount,'reason'=>$sourceReason,'book_treatment'=>$treatment,'book_treatment_explanation'=>$treatment==='EXISTING_APPROVED_ADJUSTING_JOURNAL'?'Exact delta from the linked existing approved adjusting journal; original check credit is not counted again.':'Independent verified statement reconciling item. It does not post a fund/accounting ledger entry; charges and interest await a separately authorized journal. Actual cash capacity includes the verified adjustment.','accounting_line_id'=>$line,'accounting_version_id'=>$line?(int)$r['accounting_version_id']:null,'fund_event_id'=>$event],JSON_THROW_ON_ERROR)]);return ['source_id'=>$id];
    }
    public function read(array $d):array {
        $org=idOf($d,'organization_id');$this->auth($org);$bank=idOf($d,'bank_account_id');$this->bank($org,$bank);$p=self::period($d);$r=$this->latest($org,'FR456_BANK_'.$bank.'_'.$p);$base=$this->latest($org,'FR456_BANK_BASE_'.$bank);$legacy=one($this->db,'SELECT * FROM bank_reconciliations WHERE bank_account_id=? AND period=?',[$bank,$p]);if($legacy)$legacy['lines']=q($this->db,'SELECT * FROM reconciliation_lines WHERE reconciliation_id=? ORDER BY id',[$legacy['id']])->fetchAll();
        $body=$r?json_decode($r['config_json'],true,512,JSON_THROW_ON_ERROR):null;
        $sources=q($this->db,'SELECT * FROM bank_reconciliation_sources WHERE organization_id=? AND bank_account_id=? AND effective_date<=? ORDER BY effective_date,id LIMIT 501',[$org,$bank,(new DateTimeImmutable($p.'-01'))->format('Y-m-t')])->fetchAll();demand(count($sources)<=500,'Account sources exceed safe workpaper capacity',409);
        foreach($sources as &$source){$resolution=$this->latest($org,'FR456_BANK_RESOLVE_'.$bank.'_'.$source['id']);$source['resolution']=$resolution?json_decode($resolution['config_json'],true,512,JSON_THROW_ON_ERROR):null;$source['resolved_at_cutoff']=$source['resolution']!==null&&$source['resolution']['resolved_date']<=(new DateTimeImmutable($p.'-01'))->format('Y-m-t');}unset($source);
        return ['version_id'=>(int)($r['id']??0),'draft'=>$body,'legacy'=>$legacy,'opening'=>$base?json_decode($base['config_json'],true,512,JSON_THROW_ON_ERROR):null,'sources'=>$sources,'closure_available'=>$base!==null&&($body['status']??'')!=='CLOSED'&&(!$legacy||$legacy['status']!=='CLOSED'||((int)($body['legacy_id']??0)===(int)$legacy['id']&&$this->hasLegacyReopen($org,$bank,$p,(int)$legacy['id']))),'closure_blocker'=>$base?'Closure requires all verified sources, complete check histories and exact adjusted equality.':'Verify an opening, maintaining balance and complete account sources before closure.'];
    }
    private function hasLegacyReopen(int $org,int $bank,string $period,int $legacyId):bool {
        $rows=q($this->db,"SELECT v.config_json FROM configuration_versions v WHERE v.organization_id=? AND v.config_key=? AND EXISTS(SELECT 1 FROM audit_events a WHERE a.organization_id=v.organization_id AND a.entity_id=v.id AND a.entity_type='BANK_RECONCILIATION' AND a.event_type='BANK_RECONCILIATION_REOPENED') ORDER BY v.id DESC LIMIT 501",[$org,'FR456_BANK_'.$bank.'_'.$period])->fetchAll();demand(count($rows)<=500,'Reconciliation reopen history exceeds review capacity',409);
        foreach($rows as $row){$v=json_decode($row['config_json'],true,512,JSON_THROW_ON_ERROR);if(($v['status']??'')==='REOPENED'&&(int)($v['legacy_id']??0)===$legacyId)return true;}return false;
    }
    private function workpaper(array $d):array {
        $org=idOf($d,'organization_id');$this->auth($org,true);FinancialCutoff::beginWriter($this->db,$this->user,'finance.review.bank',$d);$bank=idOf($d,'bank_account_id');$this->bank($org,$bank,true);$p=self::period($d);$end=(new DateTimeImmutable($p.'-01'))->format('Y-m-t');$from=$p.'-01';
        $key='FR456_BANK_'.$bank.'_'.$p;$r=$this->latest($org,$key);$expected=$d['expected_version']??null;demand(is_int($expected)&&$expected===(int)($r['id']??0),'Draft changed in another session. Reload before saving.',409);$prior=$r?json_decode($r['config_json'],true,512,JSON_THROW_ON_ERROR):[];demand(($prior['status']??'')!=='CLOSED','Closed reconciliation requires audited reopening',409);
        $legacy=one($this->db,"SELECT id FROM bank_reconciliations WHERE bank_account_id=? AND period=? AND status='CLOSED'",[$bank,$p]);if($legacy)demand((int)($prior['legacy_id']??0)===(int)$legacy['id']&&$this->hasLegacyReopen($org,$bank,$p,(int)$legacy['id']),'Reopen the original legacy close through its audited dependency protocol before revising this period',409);
        $base=$this->latest($org,'FR456_BANK_BASE_'.$bank);demand($base!==null,'Closure blocked: authoritative verified opening and maintaining balance are missing',409);$opening=json_decode($base['config_json'],true,512,JSON_THROW_ON_ERROR);demand($from>=$opening['start_date'],'Period predates the verified opening',409);
