        $book=(int)$opening['opening_cents'];$credits=q($this->db,"SELECT * FROM fund_events WHERE organization_id=? AND bank_account_id=? AND event_type='ALLOTMENT' AND bank_credit_date BETWEEN ? AND ? ORDER BY id LIMIT 5001",[$org,$bank,$opening['start_date'],$end])->fetchAll();demand(count($credits)<=5000,'Credit history exceeds safe close capacity',409);
        foreach($credits as $e){demand(trim((string)$e['bank_credit_ref'])!==''&&trim((string)$e['bank_evidence_ref'])!=='','Unverified account credit prevents closure',409);$book+=moneyCents((string)$e['amount']);}
        $checks=q($this->db,'SELECT c.* FROM checks c JOIN disbursement_vouchers v ON v.id=c.dv_id AND v.organization_id=c.organization_id WHERE c.organization_id=? AND c.bank_account_id=? AND c.created_at>=? AND c.created_at<? ORDER BY c.id LIMIT 5001',[$org,$bank,$opening['start_date'].' 00:00:00',(new DateTimeImmutable($end))->modify('+1 day')->format('Y-m-d').' 00:00:00'])->fetchAll();demand(count($checks)<=5000,'Check history exceeds safe close capacity',409);
        $events=q($this->db,'SELECT p.* FROM payment_events p JOIN checks c ON c.id=p.check_id WHERE c.organization_id=? AND c.bank_account_id=? ORDER BY p.created_at,p.id LIMIT 10001',[$org,$bank])->fetchAll();demand(count($events)<=10000,'Payment history exceeds safe close capacity',409);$outstanding=[];
        foreach($checks as $c){$ce=array_values(array_filter($events,static fn($e)=>(int)$e['check_id']===(int)$c['id']&&substr($e['created_at'],0,10)<=$end));demand(count(array_filter($ce,static fn($e)=>$e['event_type']==='ISSUED'))===1,'Complete unique issue history required for every check',409);
            $state='NEW';$transitions=['NEW'=>['ISSUED'],'ISSUED'=>['SIGNED','CANCELLED','STOPPED','STALE'],'SIGNED'=>['RELEASED','CANCELLED','STOPPED','STALE'],'RELEASED'=>['CLEARED','STOPPED','STALE'],'STOPPED'=>['REPLACED','CANCELLED'],'STALE'=>['REPLACED','CANCELLED'],'CLEARED'=>[],'CANCELLED'=>[],'REPLACED'=>[]];
            foreach($ce as $e){demand(in_array($e['event_type'],$transitions[$state]??[],true),'Invalid or incomplete check lifecycle prevents closure',409);$state=$e['event_type'];}
            if((int)($c['replaces_check_id']??0)>0){$ancestor=one($this->db,'SELECT * FROM checks WHERE id=? AND organization_id=? AND bank_account_id=? AND dv_id=?',[$c['replaces_check_id'],$org,$bank,$c['dv_id']]);demand($ancestor!==null&&(int)$ancestor['id']<(int)$c['id']&&moneyCents((string)$ancestor['amount'])===moneyCents((string)$c['amount'])&&CashFundReports::stageAt($ancestor,$events,$end)==='REPLACED','Replacement ancestry is missing, foreign or not resolved at cutoff',409);}
            $stage=CashFundReports::stageAt($c,$ce,$end);if(in_array($stage,['CANCELLED','REPLACED'],true)){demand(count(array_filter($ce,static fn($e)=>in_array($e['event_type'],['CANCELLED','REPLACED'],true)))===1,'Ambiguous check reversal prevents closure',409);continue;}demand(!in_array($stage,['STOPPED','STALE'],true),'Resolve stopped or stale instruments before closure',409);$book-=moneyCents((string)$c['amount']);if($stage!=='CLEARED')$outstanding[(int)$c['id']]=$c;}
        $all=q($this->db,'SELECT * FROM bank_reconciliation_sources WHERE organization_id=? AND bank_account_id=? AND effective_date BETWEEN ? AND ? ORDER BY id LIMIT 501',[$org,$bank,$opening['start_date'],$end])->fetchAll();demand(count($all)<=500,'Adjustment source capacity exceeded',409);$sources=[];$required=[];$resolved=[];
        foreach(q($this->db,"SELECT config_json FROM configuration_versions WHERE organization_id=? AND LEFT(config_key,19)='FR456_BANK_RESOLVE_'",[$org])->fetchAll() as $row){$v=json_decode($row['config_json'],true,512,JSON_THROW_ON_ERROR);if((int)$v['bank_account_id']===$bank&&$v['resolved_date']<=$end)$resolved[(int)$v['source_id']]=true;}
        foreach($all as $s){$kind=$s['kind'];if(isset($resolved[(int)$s['id']]))continue;$bookSide=in_array($kind,['BANK_CHARGE','BANK_INTEREST','BOOK_ERROR_ADD','BOOK_ERROR_SUBTRACT'],true);if($bookSide&&$s['effective_date']<$from){$book+=(in_array($kind,['BANK_INTEREST','BOOK_ERROR_ADD'],true)?1:-1)*moneyCents((string)$s['amount']);continue;}if($s['effective_date']>=$from||!$bookSide){$sources[(int)$s['id']]=$s;$required[(int)$s['id']]=true;}}
        $verified=[];$used=[];$checkUsed=[];$ls=$d['lines']??[];demand(is_array($ls)&&count($ls)<=500,'Invalid adjustment list');foreach($ls as $l){demand(is_array($l),'Invalid source selection');if(!empty($l['source_id'])){$id=idOf($l,'source_id');demand(isset($sources[$id])&&!isset($used[$id]),'Missing, foreign, duplicate or out-of-period adjustment',409);$s=$sources[$id];$used[$id]=true;$kind=$s['kind'];$verified[]=['kind'=>$kind,'side'=>in_array($kind,['BANK_CHARGE','BANK_INTEREST','BOOK_ERROR_ADD','BOOK_ERROR_SUBTRACT'],true)?'BOOK':'BANK','cents'=>moneyCents((string)$s['amount']),'source_key'=>'bank-source:'.$id,'source_id'=>$id,'evidence'=>$s['evidence_reference'],'statement_reference'=>$s['statement_reference'],'verification_reference'=>$s['verification_reference']];}else{$id=idOf($l,'check_id');demand(isset($outstanding[$id])&&!isset($checkUsed[$id]),'Check is not a unique outstanding item at cutoff',409);$checkUsed[$id]=true;$verified[]=['kind'=>'OUTSTANDING_CHECK','side'=>'BANK','cents'=>moneyCents((string)$outstanding[$id]['amount']),'source_key'=>'check:'.$id,'check_id'=>$id,'evidence'=>requiredString($l,'evidence',255)];}}
        demand(count($checkUsed)===count($outstanding),'All outstanding checks must be included; incomplete account cannot close',409);foreach($required as $id=>$v)demand(isset($used[$id]),'All unresolved bank sources and verified book adjustments must be included',409);
        $statement=self::signed($d['statement_balance']??null);if(isset($d['book_balance']))demand(self::signed($d['book_balance'])===$book,'Submitted book balance differs from verified account ledger',409);
        try{$totals=FinancialClosePolicy::reconcile($statement,$book,$verified);}catch(DomainException $e){throw new DomainError($e->getMessage(),422);}
        $body=['schema'=>2,'report_version'=>'0.2.456-development-R2','status'=>'DRAFT','bank_account_id'=>$bank,'period'=>$p,'statement_cents'=>$statement,'book_cents'=>$book,'statement_evidence'=>requiredString($d,'statement_evidence',255),'book_evidence'=>'SERVER_ACCOUNT_LEDGER_FROM_OPENING_'.$base['id'],'opening_version_id'=>(int)$base['id'],'maintaining_cents'=>(int)$opening['maintaining_cents'],'lines'=>$verified,'totals'=>$totals,'predecessor_id'=>$expected,'legacy_id'=>$prior['legacy_id']??null,'actor_id'=>(int)$this->user['id'],'reason'=>requiredString($d,'reason',500),'captured_at'=>date('c'),'book_completeness'=>'VERIFIED_FROM_OPENING','certified'=>false];return [$org,$key,$body,$opening];
    }
    public function saveDraft(array $d):array {demand(($d['close']??false)===false,'Use verified bank closure with authoritative ledger',409);demand(($d['reopen']??false)===false,'Use dependency-safe audited reopening',409);[$org,$key,$body]=$this->workpaper($d);$id=$this->append($org,$key,$body,$body['reason'],'FINANCE_REVIEW_DRAFT_SAVED');return ['version_id'=>$id,'draft'=>$body,'closed'=>false];}
    public function close(array $d):array {[$org,$key,$body,$opening]=$this->workpaper($d);$end=(new DateTimeImmutable($body['period'].'-01'))->format('Y-m-t');demand($end<date('Y-m-d'),'Month end has not occurred',409);demand($body['totals']['balanced'],'Account is unreconciled; exact adjusted equality is required',409);demand($body['totals']['adjusted_book_cents']>=$body['maintaining_cents'],'Maintaining balance would not be preserved',409);
        if($body['period']>substr($opening['start_date'],0,7)){$prev=(new DateTimeImmutable($body['period'].'-01'))->modify('-1 month')->format('Y-m');$r=$this->latest($org,'FR456_BANK_'.$body['bank_account_id'].'_'.$prev);demand($r&&json_decode($r['config_json'],true)['status']==='CLOSED','Close preceding account period first',409);}
        foreach(FinancialCutoff::closed($this->db,$org) as $later)demand($later['period']<=$body['period'],'Reopen later financial periods before revising an earlier close',409);
        $legacy=one($this->db,'SELECT id FROM bank_reconciliations WHERE bank_account_id=? AND period=?',[$body['bank_account_id'],$body['period']]);if($legacy)$body['legacy_id']=(int)$legacy['id'];
        $body['status']='CLOSED';$body['closed_at']=date('c');$id=$this->append($org,$key,$body,$body['reason'],'BANK_RECONCILIATION_CLOSED');require_once __DIR__.'/FinancialSnapshots.php';$snapshot=(new FinancialSnapshots($this->db,$this->user))->captureAtClose($org,$body['bank_account_id'],$body['period'],$id,$body['reason']);return ['version_id'=>$id,'draft'=>$body,'closed'=>true,'snapshot_id'=>$snapshot['snapshot_id']];
    }
    public function reopen(array $d):array {
        $org=idOf($d,'organization_id');$this->auth($org,true);FinancialCutoff::beginWriter($this->db,$this->user,'finance.review.bank',$d);$bank=idOf($d,'bank_account_id');$this->bank($org,$bank,true);$p=self::period($d);$r=$this->latest($org,'FR456_BANK_'.$bank.'_'.$p);
        demand(is_int($d['expected_version']??null)&&(int)($r['id']??0)===$d['expected_version'],'Refresh the closed reconciliation version',409);
        if($r)$b=json_decode($r['config_json'],true,512,JSON_THROW_ON_ERROR);
        if(!$r||($b['status']??'')!=='CLOSED'){$priorDraft=$r?$b:null;$legacy=one($this->db,"SELECT * FROM bank_reconciliations WHERE bank_account_id=? AND period=? AND status='CLOSED'",[$bank,$p]);demand($legacy!==null,'No closed reconciliation exists',409);$b=['schema'=>2,'bank_account_id'=>$bank,'period'=>$p,'legacy_id'=>(int)$legacy['id'],'preserved_draft_version_id'=>(int)($r['id']??0),'preserved_draft'=>$priorDraft,'legacy_evidence'=>$legacy,'legacy_lines'=>q($this->db,'SELECT * FROM reconciliation_lines WHERE reconciliation_id=? ORDER BY id',[$legacy['id']])->fetchAll(),'book_completeness'=>'UNVERIFIED_LEGACY','statement_cents'=>self::signed((string)$legacy['statement_balance']),'book_cents'=>self::signed((string)$legacy['book_balance']),'maintaining_cents'=>0,'maintaining_balance_status'=>'NOT_VERIFIED_LEGACY_NOTES_PRESERVED','totals'=>FinancialClosePolicy::reconcile(self::signed((string)$legacy['statement_balance']),self::signed((string)$legacy['book_balance']),[]),'lines'=>[],'certified'=>false];}
        foreach(FinancialCutoff::closed($this->db,$org) as $c)demand($c['period']<=$p,'Reopen later dependent financial periods first',409);
        foreach(FinancialCutoff::legacyClosed($this->db,$org) as $c)demand($c['period']<=$p,'Reopen later dependent legacy financial periods first',409);
        $b['status']='REOPENED';$b['predecessor_id']=(int)($r['id']??0);$b['reason']=requiredString($d,'reason',500);$b['actor_id']=(int)$this->user['id'];$b['reopened_at']=date('c');$id=$this->append($org,'FR456_BANK_'.$bank.'_'.$p,$b,$b['reason'],'BANK_RECONCILIATION_REOPENED');return ['version_id'=>$id,'draft'=>$b,'closed'=>false,'historical_snapshots_preserved'=>true];
    }
}
